int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);std::cout.setf(std::ios::unitbuf);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<"\n";QTemporaryDir temp;check(temp.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_GRADIENT_COLOR_OPENER_ROOT"),root=requested.isEmpty()?temp.path():requested;int failures=0;for(int mode=0;mode<18;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Gradient Color opener cases failed: "+std::to_string(failures));std::cout<<"PASS Gradient Color opener "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Gradient Color opener "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
